<script setup>
import { computed, onMounted, reactive, ref } from 'vue';
import { brewApi } from '../api';
const props=defineProps({supplier:{type:Boolean,default:false},catalog:{type:Boolean,default:false}});
const schema=ref({types:[],categories:[],suppliers:[],beers:[],parents:[]}),items=ref([]),total=ref(0),page=ref(1),keyword=ref(''),includeInactive=ref(false),loading=ref(false),saving=ref(false),error=ref(''),formError=ref(''),editor=ref(false),review=ref(null),canManage=ref(false),canManageCatalog=ref(false);
const draft=reactive({}),reviewNote=ref(''),parentId=ref('');
const stateNames={draft:'草稿',submitted:'待确认',confirmed:'可用',returned:'需修改'};
const labels={capacity:'容量',material:'材质',closure:'口径 / 接口规格',position:'标签位置',dimensions:'尺寸',pack_count:'每箱装载数量',color:'颜色',supplier_code:'供应商货号',procurement_unit:'采购单位',unit_quantity:'每采购单位含多少库存单位',quote_price:'报价 / 采购单位',min_order:'起订量（采购单位）',lead_days:'交货周期（天）',artwork_version:'图稿版本',notes:'规格说明'};
const type=computed(()=>schema.value.types.find(t=>t.code===draft.type));
const fields=computed(()=>type.value?.fields||[]);
const groups=computed(()=>[...new Set(schema.value.types.map(item=>item.group))]);
const canWrite=computed(()=>props.catalog?canManageCatalog.value:(props.supplier||canManage.value));
async function load(){loading.value=true;error.value='';try{const data=await brewApi.listPackaging({page:page.value,page_size:30,keyword:keyword.value,include_inactive:includeInactive.value,catalog_only:props.catalog});items.value=data.items;total.value=data.total;canManage.value=data.can_manage;canManageCatalog.value=data.can_manage_catalog===true;}catch(e){error.value=e.message;}finally{loading.value=false;}}
function unitPrice(item){const price=item.details?.quote_price;const quantity=Number(item.details?.unit_quantity||1);return price===undefined||price===null||price===''||!Number.isFinite(quantity)||quantity<=0?null:Number(price)/quantity;}
function priceText(item){const value=unitPrice(item);return value===null?'—':value.toLocaleString('zh-CN',{maximumFractionDigits:6});}
function open(item=null){formError.value='';Object.keys(draft).forEach(k=>delete draft[k]);Object.assign(draft,item?JSON.parse(JSON.stringify({...item,supplier_id:item.supplier?.id||'',image:undefined,existingImage:item.image})):{name:'',code:'',category_code:'',type:'',supplier_id:'',details:{unit:'个',capacity_unit:'mL',procurement_unit:'个',unit_quantity:1,quote_price:'',custom:false}});if(item){draft.details.quote_price=unitPrice(item)??'';draft.details.procurement_unit='个';draft.details.unit_quantity=1;}editor.value=true;}
function categoryChanged(){draft.type=schema.value.categories.find(c=>c.code===draft.category_code)?.type||'';const unit=draft.type==='label'?'张':'个';draft.details={unit,capacity_unit:draft.type==='keg'?'L':'mL',procurement_unit:unit,unit_quantity:1,quote_price:'',custom:false,...(draft.type==='carton'?{dimension_basis:'内尺寸'}:{})};}
async function save(){saving.value=true;formError.value='';try{if(props.catalog&&!draft.supplier_id)throw new Error('请选择系统设置中的供应商。');const data={supplier_catalog:props.catalog,name:draft.name,code:draft.code,category_code:draft.category_code,type:draft.type,details:{...draft.details,unit:'个',procurement_unit:'个',unit_quantity:1},supplier_id:draft.supplier_id,version:draft.version};if(draft.image!==undefined)data.image=draft.image;await brewApi.savePackaging(draft.id,data);editor.value=false;await load();}catch(e){formError.value=e.message;}finally{saving.value=false;}}
async function action(item,name){saving.value=true;error.value='';try{await brewApi.packagingAction(item.id,name,{supplier_catalog:props.catalog,version:item.version,note:reviewNote.value,parent_id:parentId.value||null});review.value=null;await load();}catch(e){if(review.value)formError.value=e.message;else error.value=e.message;}finally{saving.value=false;}}
async function remove(item){if(!window.confirm(`确定删除包装材料“${item.name}”吗？删除后可在“包含停用”中恢复。`))return;await action(item,'archive');}
function startReview(item){review.value=item;reviewNote.value='';parentId.value='';formError.value='';}
function readFile(event,kind){const f=event.target.files[0];if(!f)return;if(kind==='image'&&!['image/jpeg','image/png','image/webp'].includes(f.type)){formError.value='商品图片仅支持 JPG、PNG 或 WebP。';event.target.value='';return;}if(f.size>(kind==='image'?5:3)*1024*1024){formError.value=kind==='image'?'商品图片请控制在 5 MB 以内。':'图稿附件请控制在 3 MB 以内。';event.target.value='';return;}formError.value='';const reader=new FileReader();reader.onload=()=>{const base=String(reader.result).split(',')[1];if(kind==='image')draft.image=base;else{draft.details.artwork_data=base;draft.details.artwork_name=f.name;}};reader.readAsDataURL(f);}
function clearImage(){draft.image='';draft.existingImage='';}
function specification(item){const t=schema.value.types.find(t=>t.code===item.type);return t?.fields.filter(field=>item.details[field.key]!==undefined&&item.details[field.key]!==''&&(!item.details.dimensions||!['length_mm','width_mm','height_mm'].includes(field.key))).map(field=>`${field.label}：${item.details[field.key]}${field.key==='capacity'?' '+item.details.capacity_unit:field.unit?' '+field.unit:''}`).join(' · ')||'待补充规格';}
onMounted(async()=>{try{schema.value=await brewApi.packagingSchema();await load();}catch(e){error.value=e.message;}});
</script>
<template>
<section class="packaging-page">
<header class="packaging-toolbar"><div><h3>{{ catalog?'供应商包装产品':supplier?'我的包装商品':'包装材料' }}</h3><p>{{ catalog ? '按供应商查看可采购的包装材料，供应商名称显示在每件商品上。' : supplier ? '商品仅属于当前供应商，保存后直接可用，不自动加入酒厂材料库。' : '酒厂自己的酒瓶、易拉罐、酒桶和纸箱 / 礼盒材料。' }}</p></div><label v-if="!catalog || canWrite" class="pack-show-inactive"><input v-model="includeInactive" type="checkbox" @change="page=1;load()">包含停用</label><input v-model.trim="keyword" :placeholder="catalog?'搜索商品或供应商':'搜索包装材料'" @keyup.enter="page=1;load()"><button class="btn btn-sm btn-outline" @click="page=1;load()">搜索</button><button v-if="canWrite" class="btn btn-sm btn-primary" @click="open()">{{ catalog ? '录入供应商商品' : '新增包装材料' }}</button></header>
<div v-if="error" class="master-error">{{ error }}</div><div v-if="loading" class="empty">正在加载…</div>
<div v-else-if="catalog" class="pack-offer-grid"><article v-for="item in items" :key="item.id" class="pack-offer-card"><header><span>{{ schema.categories.find(c=>c.code===item.category_code)?.name||'包装材料' }}</span><strong>{{ item.supplier?.name||'供应商' }}</strong></header><img v-if="item.image" class="pack-offer-image" :src="'data:image/jpeg;base64,'+item.image" :alt="item.name"><h3>{{ item.name }}</h3><p>{{ specification(item) }}</p><footer><span>报价<strong>¥{{ priceText(item) }} / 个</strong></span><span>规格<strong>{{ item.details.procurement_unit||item.unit||'个' }}</strong></span><span class="pack-state confirmed">可供货</span></footer><button class="btn btn-xs btn-outline" type="button" @click="review=item">查看详情</button><button v-if="canWrite" class="btn btn-xs btn-outline" type="button" @click="open(item)">编辑商品</button><button v-if="canWrite && item.active" class="btn btn-xs btn-danger" type="button" :disabled="saving" @click="remove(item)">删除</button><button v-if="canWrite && !item.active" class="btn btn-xs btn-outline" type="button" :disabled="saving" @click="action(item,'restore')">恢复</button></article><div v-if="!items.length" class="empty">暂无可采购的供应商包装产品。</div></div>
<div v-else class="work-table-wrap"><table class="work-table"><thead><tr><th>材料 / 规格</th><th>类型</th><th>供应商</th><th>单价（元 / 个）</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="item in items" :key="item.id"><td><div class="pack-material-cell"><img v-if="item.image" class="pack-row-image" :src="'data:image/jpeg;base64,'+item.image" :alt="item.name"><span v-else class="pack-row-placeholder">{{ item.name.slice(0,1) }}</span><strong>{{ item.name }}</strong></div><small>{{ specification(item) }}</small><small v-if="item.details.custom">{{ schema.beers.find(b=>b.id===String(item.details.beer_product_id))?.name }} · {{ item.details.artwork_version }}</small></td><td>{{ schema.categories.find(c=>c.code===item.category_code)?.name||'包装材料' }}</td><td>{{ item.supplier?.name||'酒厂通用材料' }}</td><td>¥{{ priceText(item) }} / 个</td><td><span :class="['pack-state',item.state]">{{ item.active ? stateNames[item.state] : '已停用' }}</span><small v-if="item.review_note">{{ item.review_note }}</small><small v-if="item.parent">关联 {{ item.parent.name }}</small></td><td class="pack-actions"><button v-if="canWrite" class="btn btn-xs btn-outline" @click="open(item)">详情/编辑</button><button v-if="canWrite && item.active" class="btn btn-xs btn-danger" :disabled="saving" @click="remove(item)">删除</button><button v-if="canWrite && !item.active" class="btn btn-xs btn-outline" :disabled="saving" @click="action(item,'restore')">恢复</button></td></tr></tbody></table><div v-if="!items.length" class="empty">暂无包装材料，先在原料种类中维护包装小类。</div></div>
<footer class="pack-pagination"><span>共 {{ total }} 件</span><button class="btn btn-xs btn-outline" :disabled="page<=1||loading" @click="page--;load()">上一页</button><span>{{ page }}</span><button class="btn btn-xs btn-outline" :disabled="page*30>=total||loading" @click="page++;load()">下一页</button></footer>
<Teleport to="body"><div v-if="editor" class="equipment-modal-mask" @click.self="!saving&&(editor=false)"><section class="equipment-modal pack-editor" role="dialog" aria-modal="true" aria-label="录入包装材料"><header class="equipment-modal-header"><div class="modal-title">{{ draft.id?'包装材料详情 / 编辑':'新增包装材料' }}</div><button class="equipment-close" :disabled="saving" @click="editor=false">×</button></header><form @submit.prevent="save"><div class="pack-form"><label>材料名称<input v-model.trim="draft.name" required></label><label>材料编码<input v-model.trim="draft.code" placeholder="选填"></label><label>包装材料类型<select v-model="draft.category_code" required @change="categoryChanged"><option value="">选择纸箱、酒瓶或其他材料类型</option><optgroup v-for="group in groups" :key="group" :label="group"><option v-for="c in schema.categories.filter(c=>schema.types.find(t=>t.code===c.type)?.group===group)" :key="c.code" :value="c.code">{{ schema.types.find(t=>t.code===c.type)?.name || c.name }}</option></optgroup></select></label><label v-if="!supplier">供应商<select v-model="draft.supplier_id" :required="catalog" aria-label="商品所属供应商"><option value="">{{ catalog ? '请选择系统设置中的供应商' : '酒厂通用材料，暂不关联' }}</option><option v-for="s in schema.suppliers" :key="s.id" :value="s.id">{{ s.name }}</option></select></label>
<template v-if="draft.type"><div class="pack-wide pack-section-title">{{ type?.name }}规格</div><p v-if="draft.type === 'carton'" class="pack-wide rw-hint">长、宽、高按内尺寸填写，单位 mm；填写每箱数量及适用瓶 / 罐容量。</p><p v-if="draft.type === 'bottle'" class="pack-wide rw-hint">填写酒瓶容量、材质和尺寸，用于匹配装箱需求。</p><label v-for="field in fields" :key="field.key"><span>{{ field.required ? '* ' : '' }}{{ field.label }}{{ field.unit ? '（'+field.unit+'）' : '' }}</span><div v-if="field.input==='capacity'" class="pack-capacity"><input v-model.number="draft.details.capacity" type="number" min="0.001" step="any" required><select v-model="draft.details.capacity_unit"><option>mL</option><option>L</option></select></div><select v-else-if="field.input==='select'" v-model="draft.details[field.key]" :required="field.required"><option value="">请选择</option><option v-for="option in field.options" :key="option" :value="option">{{ option }}</option></select><input v-else v-model="draft.details[field.key]" :type="field.input==='number'?'number':'text'" :min="field.input==='number'?(['pack_count','grid_count'].includes(field.key)?1:0.000001):undefined" :step="['pack_count','grid_count'].includes(field.key)?1:'any'" :required="field.required" :placeholder="field.key==='dimensions'?'旧规格可查看，新增材料请填写独立尺寸字段':field.key==='closure'?'填写实际瓶口、盖口或接口型号':''"></label><div class="pack-wide pack-section-title">库存与单价</div>
<label>库存单位<select v-model="draft.details.unit"><option v-for="u in ['film','strap'].includes(draft.type)?['kg','m']:draft.type==='label'?['张']:['个']" :key="u">{{ u }}</option></select></label><label>单价（元 / 个）<input v-model.number="draft.details.quote_price" type="number" min="0" step="any" required placeholder="填写单个材料的价格"></label><div class="pack-wide pack-image-field"><span>商品图片（选填）</span><div class="pack-image-uploader"><div class="pack-preview"><img v-if="draft.image||draft.existingImage" :src="'data:image/jpeg;base64,'+(draft.image||draft.existingImage)" alt="商品图片预览"><span v-else>商品图片预览</span></div><div class="pack-image-controls"><label class="btn btn-sm btn-outline">{{ draft.image||draft.existingImage?'更换图片':'选择图片' }}<input type="file" accept="image/jpeg,image/png,image/webp" @click="$event.target.value=null" @change="readFile($event,'image')"></label><button v-if="draft.image||draft.existingImage" type="button" class="btn btn-sm btn-secondary" @click="clearImage">移除图片</button><small>支持 JPG、PNG、WebP，最大 5 MB</small></div></div></div><label class="pack-wide">规格说明<textarea v-model.trim="draft.details.notes" rows="2"></textarea></label></template><div v-if="formError" class="master-error pack-wide">{{ formError }}</div></div><footer class="equipment-modal-footer"><button type="button" class="btn btn-secondary" :disabled="saving" @click="editor=false">取消</button><button class="btn btn-primary" :disabled="saving||!draft.type">{{ saving?'保存中…':'保存材料' }}</button></footer></form></section></div>
<div v-if="review" class="equipment-modal-mask" @click.self="!saving&&(review=null)"><section class="equipment-modal pack-review" role="dialog" aria-modal="true" aria-label="包装商品详情"><header class="equipment-modal-header"><div class="modal-title">{{ review.name }}</div><button class="equipment-close" @click="review=null">×</button></header><div class="pack-form"><img v-if="review.image" class="pack-detail-image pack-wide" :src="'data:image/jpeg;base64,'+review.image" :alt="review.name"><p class="pack-wide">{{ specification(review) }}</p><div class="pack-detail-meta pack-wide"><span>供应商</span><strong>{{ review.supplier?.name||'—' }}</strong><span>单价</span><strong>¥{{ priceText(review) }} / 个</strong><span>状态</span><strong>{{ stateNames[review.state]||review.state }}</strong></div></div><footer class="equipment-modal-footer"><button class="btn btn-secondary" @click="review=null">关闭</button></footer></section></div></Teleport>
</section>
</template>
<style scoped>
