ew{width:min(560px,95vw)}@media(max-width:600px){.pack-form{grid-template-columns:1fr;padding:16px}.pack-image-uploader{align-items:flex-start;flex-direction:column}}
.pack-material-cell{display:flex;align-items:center;gap:10px;min-width:180px}.pack-row-image,.pack-row-placeholder{display:grid;place-items:center;width:42px;height:42px;flex:0 0 42px;overflow:hidden;box-sizing:border-box;border:1px solid var(--border-default);border-radius:7px;background:var(--bg-input)}.pack-row-image{object-fit:cover}.pack-row-placeholder{color:var(--accent-gold);font-size:16px}.pack-section-title{font-size:14px;font-weight:700;padding-top:12px;border-top:1px solid var(--border-default)}
