.pack-form input:not([type="checkbox"]),.pack-form select,.pack-form textarea,.packaging-toolbar>input{width:100%;min-width:0;min-height:40px;padding:8px 10px;border:1px solid var(--border-default);border-radius:7px;background:var(--bg-input);color:var(--text-primary);font:inherit;box-sizing:border-box;color-scheme:dark}
